/**
 * Fit the transcript into the summary budget without dropping the end of the
 * meeting. Tasks are usually handed out during the wrap-up, so a plain
 * head-only cut (the old behaviour) silently lost them on longer meetings.
 * Keeps the opening for context and gives most of the budget to the ending.
 */
private static trimContextForSummary(context: string, maxChars = 10000): string {
    if (context.length <= maxChars) return context;
    const marker = '\n[...middle of meeting omitted...]\n';
    const headChars = Math.floor((maxChars - marker.length) * 0.3);
    const tailChars = maxChars - marker.length - headChars;
    return context.slice(0, headChars) + marker + context.slice(-tailChars);
}

